method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures (result == true <==> countOpening(brackets) == countClosing(brackets)) 
    ensures (result == true <==> validBracketing(brackets))

    // Helper function to count opening brackets
    function countOpening(s: string): int
        requires s != null
        ensures 0 <= countOpening(s) <= s.Length
    {
        var count := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= i <= s.Length
            invariant count == CountOpening(s[0..i])
        {
            if s[i] == '(' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // Helper function to count closing brackets
    function countClosing(s: string): int
        requires s != null
        ensures 0 <= countClosing(s) <= s.Length
    {
        var count := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= i <= s.Length
            invariant count == CountClosing(s[0..i])
        {
            if s[i] == ')' {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

    // Helper function to validate if the bracket sequence is correct
    function validBracketing(s: string): bool
        requires s != null
    {
        var balance := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= i <= s.Length
            invariant balance >= 0
        {
            if s[i] == '(' {
                balance := balance + 1;
            } else if s[i] == ')' {
                balance := balance - 1;
            }
            i := i + 1;
        }
        return balance == 0;
    }
```

